[SubscribesTo(classStr(AVAPCMEmailFormatter), delegateStr(AVAPCMEmailFormatter, onContractSet))]
public static void onContractSetDelegate(Object _rdpContract)
{
    AVASalesOrderDelegationReportContract   locAVASalesOrderDelegationReportContract;
    RefTableId                              locRefTableId;
    RefRecId                                locRefRecId;

    switch (true)
    {
        case _rdpContract is AVASalesOrderDelegationReportContract:
            locAVASalesOrderDelegationReportContract    = _rdpContract as AVASalesOrderDelegationReportContract;
            locRefTableId                               = tableNum(SalesTable);
            locRefRecId                                 = locAVASalesOrderDelegationReportContract.parmRecordId();
            break;
    }
}
